head.b:skin:
/* PT Tah Sung Hung — editorial industrial redesign */
:root{--ink:#161b1a;--paper:#f3f2ec;--white:#fbfbf6;--accent:#daf16d;--orange:#e16a45;--muted:#66706b;--hair:#c6cbc2;--dark:#18211e;--serif:"Instrument Serif",Georgia,serif;--display:"Barlow Condensed","Arial Narrow",sans-serif;--body:"DM Sans",Arial,sans-serif}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:90px}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--body);-webkit-font-smoothing:antialiased;overflow-x:hidden}
body.menu-open{overflow:hidden}
::selection{background:var(--accent);color:var(--ink)}
a{color:inherit;text-decoration:none}
button{font:inherit;cursor:pointer}
img{display:block;width:100%}
h1,h2,h3,p{margin:0}
h1,h2,h3{font-weight:700}
button,a{-webkit-tap-highlight-color:transparent}
:focus-visible{outline:2px solid var(--orange);outline-offset:4px}
.scroll-progress{position:fixed;top:0;left:0;right:auto;height:3px;width:0;background:var(--orange);z-index:1000;pointer-events:none}
.study-note{min-height:29px;padding:7px 24px;text-align:center;background:var(--accent);color:var(--ink);font-size:9px;font-weight:700;letter-spacing:.16em;line-height:1.5}
.site-header{height:80px;position:sticky;top:0;z-index:200;display:flex;align-items:center;gap:34px;justify-content:space-between;padding:0 5.5%;background:rgba(243,242,236,.97);border-bottom:1px solid #bdc3b9;backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);transition:height .25s ease,box-shadow .25s}
.site-header.scrolled{height:68px;box-shadow:0 6px 28px #161b1a10}
.identity{display:flex;align-items:center;gap:18px;flex-shrink:0}
.identity-mark{font-family:var(--display);font-size:53px;font-weight:800;letter-spacing:-.08em;line-height:.9}
.identity-dot{color:var(--orange)}
.identity-text{display:flex;flex-direction:column;gap:6px;font-size:11px;line-height:1;font-weight:700;letter-spacing:.08em}
.identity-text small{color:var(--muted);font-size:8px;letter-spacing:.14em}
.nav{display:flex;align-items:center;justify-content:center;gap:clamp(14px,2.15vw,38px)}
.nav a,.header-contact{font-size:10px;letter-spacing:.10em;font-weight:700;transition:color .2s}
.nav a{position:relative;padding:15px 0}
.nav a::after{content:"";position:absolute;left:0;right:100%;bottom:8px;height:1px;background:var(--orange);transition:right .3s ease}
.nav a:hover::after,.nav a.active::after{right:0}
.nav a:hover,.nav a.active{color:#a5452b}
.header-contact{padding:13px 0;border-bottom:1px solid var(--ink);white-space:nowrap;display:flex;align-items:center;gap:18px}
.header-contact span{font-size:17px;font-weight:400}
.menu-toggle{display:none;width:44px;height:44px;align-items:center;justify-content:center;flex-direction:column;gap:6px;border:1px solid var(--ink);background:transparent}
.menu-toggle span{width:19px;height:2px;background:var(--ink);transition:transform .3s}
.hero{display:grid;grid-template-columns:56% 44%;min-height:min(764px,calc(100svh - 108px));border-bottom:1px solid var(--hair)}
.hero-copy{min-width:0;min-height:660px;padding:45px 5.5vw 29px 5.5vw;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}
.hero-copy::before{position:absolute;content:"";height:1px;left:5.5vw;right:5.5vw;top:91px;background:var(--hair)}
.hero-meta{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:9px;font-weight:700;letter-spacing:.12em}
.hero-meta span:first-child{display:flex;align-items:center;gap:12px}
.signal{width:8px;height:8px;display:block;background:var(--orange);border-radius:50%;box-shadow:0 0 0 4px #e16a4520}
.hero-title-wrap{padding:42px 0 25px;position:relative}
.hero-prelude{font-size:10px;letter-spacing:.21em;font-weight:700;margin-bottom:21px}
.hero h1{font-family:var(--display);font-weight:800;letter-spacing:-.053em;line-height:.745;font-size:clamp(105px,12.7vw,214px);margin-left:-.036em}
.title-line{display:block;overflow:hidden;padding:0 0 .09em}
.title-line>span{display:inline-block;transform-origin:left bottom}
.title-period{color:var(--orange)}
.hero-sub{font-family:var(--serif);font-style:italic;font-size:clamp(22px,2.4vw,35px);line-height:1.08;max-width:470px;margin-top:14px;letter-spacing:-.015em}
.hero-foot{display:flex;align-items:center;gap:17px;padding-top:21px;border-top:1px solid var(--hair);font-size:9px;font-weight:700;letter-spacing:.15em}
.round-cta{width:55px;height:55px;border:1px solid var(--ink);border-radius:50%;display:grid;place-items:center;transition:background .3s,color .3s,transform .3s}
.round-cta span{font-size:26px;font-family:var(--serif);font-weight:400;transform:translateY(-2px)}
.round-cta:hover{background:var(--ink);color:var(--accent);transform:translateY(3px)}
.hero-foot-index{margin-left:auto}
.hero-media{position:relative;overflow:hidden;min-height:660px;background:#2a3332}
.hero-image{height:100%;position:absolute;inset:0;object-fit:cover;object-position:55% 50%;filter:grayscale(1) contrast(1.05) brightness(.79);transform:scale(1.06) translate3d(0,var(--photo-shift,0px),0);transition:filter 1s,transform 1.4s cubic-bezier(.2,.7,.2,1)}
.hero-media:hover .hero-image{filter:grayscale(.35) contrast(1.03) brightness(.83);transform:scale(1.015) translate3d(0,var(--photo-shift,0px),0)}
.hero-media-shade{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#080b0910 20%,#080b091c 44%,#080b09b5 100%)}
.hero-crosshair{position:absolute;inset:25px;display:flex;align-content:space-between;justify-content:space-between;flex-wrap:wrap;color:#ffffff91;font-size:29px;pointer-events:none}
.hero-crosshair span{display:block;width:50%;line-height:1}
.hero-crosshair span:nth-child(even){text-align:right}
.hero-vertical{position:absolute;top:115px;right:24px;writing-mode:vertical-rl;font-size:9px;color:#eee;letter-spacing:.18em;font-weight:700}
.image-label{position:absolute;bottom:45px;left:38px;display:flex;flex-direction:column;align-items:flex-start;color:#fff;gap:12px}
.image-label>span{font-size:9px;font-weight:700;letter-spacing:.18em;color:var(--accent)}
.image-label strong{font-family:var(--display);font-size:clamp(46px,5.25vw,82px);font-weight:700;line-height:.82;letter-spacing:-.025em}
.image-label small{font-size:8px;color:#d8ddd4;letter-spacing:.1em;margin-top:10px}
.hero-image-corner{width:65px;height:65px;position:absolute;top:0;right:0;background:var(--accent);color:var(--ink);display:grid;place-items:center;font-size:30px}
.motion-strip{height:63px;overflow:hidden;background:var(--accent);display:flex;align-items:center;border-bottom:1px solid var(--ink)}
.strip-track{display:flex;align-items:center;gap:48px;min-width:max-content;animation:slide 36s linear infinite}
.strip-track span{font-family:var(--display);font-size:26px;font-weight:700;letter-spacing:.06em}
.strip-track b{font-size:22px;font-weight:400}
@keyframes slide{to{transform:translateX(-50%)}}
.section-light{background:var(--paper)}
.section-head{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--hair);padding-bottom:18px;font-size:10px;letter-spacing:.14em;font-weight:700}
.section-number{display:flex;align-items:center;gap:13px}
.section-number::before{content:"";width:8px;height:8px;background:var(--orange)}
.section-tag{opacity:.55}
.profile{padding:105px 6% 120px}
.profile-layout{display:grid;grid-template-columns:54% 46%;gap:35px;padding:80px 0}
.profile-title h2,.org-intro h2{font:800 clamp(66px,7.25vw,123px)/.86 var(--display);letter-spacing:-.035em}
.display-label{font:700 11px var(--body);letter-spacing:.15em;display:block;margin-bottom:27px}
.outline{color:transparent;-webkit-text-stroke:1.35px var(--ink);paint-order:stroke fill}
.profile-body{padding:63px 16% 0 4%;max-width:650px}
.body-lead{font-size:clamp(17px,1.64vw,24px);font-weight:500;line-height:1.52;letter-spacing:-.025em;margin-bottom:28px}
.profile-body>p:not(.body-lead){font-size:13px;line-height:1.95;color:#49534d;margin-bottom:36px}
.underlink{font-size:10px;letter-spacing:.12em;font-weight:700;border-bottom:1px solid var(--ink);padding:14px 0;display:inline-flex;gap:36px;justify-content:space-between;transition:gap .3s}
.underlink:hover{gap:52px}
.facts{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--ink);border-bottom:1px solid var(--ink)}
.fact{min-height:190px;padding:30px 20px;display:flex;flex-direction:column;justify-content:space-between}
.fact + .fact{border-left:1px solid var(--hair)}
.fact>span{font-size:10px;letter-spacing:.13em;font-weight:700;color:var(--muted)}
.fact strong{font:700 clamp(39px,4.6vw,70px)/1 var(--display);letter-spacing:-.02em}
.fact small{font-size:11px;color:var(--muted)}
.interlude{background:var(--accent);padding:32px 6% 36px;position:relative;overflow:hidden;min-height:440px;display:flex;flex-direction:column;justify-content:space-between}
.interlude-grid{position:absolute;inset:0;opacity:.18;background-image:linear-gradient(#1b271c 1px,transparent 1px),linear-gradient(90deg,#1b271c 1px,transparent 1px);background-size:100px 100px;mask-image:linear-gradient(90deg,transparent,#000)}
.interlude-top,.interlude-bottom{display:flex;justify-content:space-between;gap:20px;position:relative;z-index:1;font-size:10px;font-weight:700;letter-spacing:.17em}
.interlude-quote{position:relative;z-index:1;font:700 clamp(39px,5.6vw,86px)/1.02 var(--display);max-width:1180px;text-transform:uppercase;letter-spacing:-.024em;padding:40px 0}
.interlude-quote em,.journal-side em,.gallery-heading h2 em,.credits-grid h2 em{font-family:var(--serif);font-weight:400;text-transform:none;letter-spacing:-.05em}
.interlude-bottom{border-top:1px solid #1b271d60;padding-top:19px}
.section-dark{background:var(--dark);color:var(--paper)}
.purpose{padding:104px 6% 0;overflow:hidden}
.dark-head{border-color:#5b625d}
.purpose-layout{padding:89px 0 80px;display:grid;grid-template-columns:51% 49%;gap:30px}
.purpose-heading{padding-right:8%}
.overline{color:var(--accent);font-size:10px;letter-spacing:.18em;font-weight:700;margin-bottom:31px}
.purpose-heading h2{font:800 clamp(85px,9.15vw,155px)/.78 var(--display);letter-spacing:-.04em}
.purpose-heading h2 em{color:var(--accent);font-style:normal}
.disclosure{max-width:400px;color:#a7b5aa;font-size:12px;line-height:1.75;margin-top:46px}
.purpose-detail{padding:10px 5% 0 0}
.tiny-label{font-size:10px;letter-spacing:.17em;font-weight:700;color:var(--accent)}
.vision-block{border-bottom:1px solid #5b625d;padding-bottom:44px;margin-bottom:45px}
.vision-block h3{font:600 clamp(27px,2.8vw,42px)/1.18 var(--display);letter-spacing:-.01em;max-width:600px;margin-top:26px;text-transform:uppercase}
.mission-list{list-style:none;margin:30px 0 0;padding:0}
.mission-list li{display:grid;grid-template-columns:30px 1fr 18px;gap:17px;align-items:start;padding:17px 0;border-top:1px solid #4b564d;transition:padding .25s,background .25s}
.mission-list li:hover{padding-left:10px;background:#ffffff08}
.mission-list span{font-size:10px;color:var(--accent);font-weight:700;margin-top:6px}
.mission-list p{font-size:13px;line-height:1.7;color:#dae3d8}
.mission-list b{font-size:15px;font-weight:400;color:var(--accent)}
.purpose-foot{border-top:1px solid #5b625d;padding:20px 0 23px;font:700 clamp(33px,4.3vw,66px) var(--display);letter-spacing:.1em;text-align:justify;display:flex;justify-content:space-between;align-items:center}
.purpose-foot span{color:var(--accent);font-size:.7em}
.organization{padding:102px 6%}
.org-layout{padding:85px 0 105px;display:grid;grid-template-columns:43% 57%;gap:55px}
.org-intro>p{max-width:355px;font-size:16px;line-height:1.7;margin-top:28px}
.org-intro .note{display:block;max-width:370px;margin-top:33px;color:var(--muted);font-size:11px;line-height:1.8}
.org-chart{padding-top:24px}
.chart-lead{font-size:12px;letter-spacing:.08em;font-weight:700;display:flex;align-items:center;justify-content:space-between;padding:25px 26px;background:var(--ink);color:var(--paper)}
.chart-lead span{font:700 21px var(--display);color:var(--accent)}
.chart-lead.secondary{background:var(--accent);color:var(--ink)}
.chart-lead.secondary span{color:var(--ink)}
.chart-connector{height:29px;width:1px;background:var(--ink);margin:0 auto;position:relative}
.chart-connector::after{content:"";position:absolute;bottom:0;left:-3px;width:7px;height:7px;transform:rotate(45deg);border-bottom:1px solid var(--ink);border-right:1px solid var(--ink)}
.department-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.department-grid span{font-size:10px;letter-spacing:.06em;font-weight:700;line-height:1.3;padding:17px 15px;background:#e7e9df;border:1px solid #d9ddd1;transition:background .2s,transform .2s}
.department-grid span:hover{background:var(--accent);transform:translateY(-2px)}
.business-row{display:grid;grid-template-columns:22% 1fr 35px;gap:36px;align-items:center;border-top:1px solid var(--ink);border-bottom:1px solid var(--ink);padding:30px 0}
.business-row>span:first-child{font-size:10px;letter-spacing:.15em;font-weight:700}
.business-row p{font:600 clamp(22px,2.3vw,32px)/1.25 var(--display);text-transform:uppercase;max-width:670px}
.business-arrow{font-size:31px}
.journal{background:#dfe4d9;color:var(--ink);padding:103px 6% 130px}
.journal-layout{display:grid;grid-template-columns:40% 60%;gap:44px;padding:79px 0 0}
.journal-side{padding-right:20%}
.journal-side .issue{font-size:11px;letter-spacing:.15em;font-weight:700;color:#667765;margin-bottom:26px}
.journal-side h2{font:800 clamp(85px,9vw,144px)/.77 var(--display);letter-spacing:-.04em}
.journal-side em{font-size:.92em}
.journal-side>p:last-child{max-width:350px;font-size:13px;line-height:1.8;margin-top:30px;color:#526153}
.journal-main{padding:8px 0 0 7%;border-left:1px solid #acb7a9}
.journal-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;border-bottom:1px solid #919b90;padding-bottom:18px;font-size:9px;font-weight:700;letter-spacing:.09em}
.journal-meta span:first-child{color:#ae4b2c}
.journal-main h3{font:700 clamp(43px,5.4vw,80px)/.95 var(--display);letter-spacing:-.028em;text-transform:uppercase;margin:33px 0 23px}
.journal-teaser{color:#546154;font-size:15px;line-height:1.85;margin-bottom:41px;max-width:590px}
.news-details{border-top:1px solid var(--ink);border-bottom:1px solid var(--ink)}
.news-details summary{list-style:none;display:flex;align-items:center;justify-content:space-between;gap:20px;cursor:pointer;outline-offset:6px;padding:24px 0;font-size:11px;font-weight:700;letter-spacing:.16em}
.news-details summary::-webkit-details-marker{display:none}
.news-details summary span{width:43px;height:43px;display:grid;place-items:center;background:var(--ink);color:var(--accent);font-size:25px;font-weight:400;transition:transform .3s}
.news-details[open] summary span{transform:rotate(45deg)}
.article-text{border-top:1px solid #aeb8aa;max-width:700px;padding:25px 0 5px}
.article-text p{margin-bottom:23px;font-size:14px;line-height:2;color:#2c3832}
.article-text .source-note{font-size:12px;color:#546154;border-top:1px solid #aeb8aa;padding-top:17px}
.gallery{padding:105px 6% 132px;background:var(--white)}
.gallery-heading{display:grid;grid-template-columns:65% 35%;align-items:end;gap:20px;margin:70px 0 40px}
.gallery-heading h2{font:800 clamp(73px,8.15vw,137px)/.78 var(--display);letter-spacing:-.04em}
.gallery-heading h2 em{font-size:.77em}
.gallery-heading p{font-size:13px;line-height:1.85;max-width:335px;color:#59635e;padding:0 3% 0 12%}
.gallery-grid{display:grid;grid-template-columns:1.14fr 1fr 1fr;gap:14px}
.gallery-item{min-width:0;display:flex;flex-direction:column}
.poster-design{background:#d9ee75;min-height:500px;padding:24px 23px 23px;position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:space-between}
.poster-top,.poster-bottom{display:flex;justify-content:space-between;align-items:center;gap:8px;position:relative;z-index:1;font-size:9px;letter-spacing:.08em;font-weight:700}
.poster-top{border-bottom:1px solid var(--ink);padding-bottom:17px}
.poster-bottom{border-top:1px solid var(--ink);padding-top:17px}
.poster-bottom span:last-child{font-size:25px}
.poster-design>p{font-size:10px;font-weight:800;letter-spacing:.15em;position:relative;z-index:2;margin-top:auto;margin-bottom:12px}
.poster-design h3{font:800 clamp(44px,4.75vw,76px)/.81 var(--display);letter-spacing:-.03em;position:relative;z-index:2;margin-bottom:auto}
.poster-design h3 em{font-family:var(--serif);font-weight:400}
.poster-design h3>span{color:var(--orange)}
.poster-orbit{position:absolute;right:-115px;top:70px;width:420px;height:420px;border:80px solid #97b45d;opacity:.37;border-radius:50%;box-shadow:0 0 0 55px #c2de85,0 0 0 110px #a8cc6a}
.gallery-image-wrap{position:relative;min-height:500px;overflow:hidden;background:#363f3a}
.gallery-image-wrap img{height:500px;object-fit:cover;filter:grayscale(.85) contrast(1.07) brightness(.88);transition:filter .5s,transform .8s}
.photo-item:nth-child(2) .gallery-image-wrap img{object-position:57% center}
.photo-item:nth-child(3) .gallery-image-wrap img{object-position:52% center}
.photo-item:hover img{filter:grayscale(0);transform:scale(1.055)}
.photo-corner{width:48px;height:48px;position:absolute;right:0;top:0;display:grid;place-items:center;color:var(--ink);background:var(--accent);font-size:22px}
.gallery-caption{display:grid;grid-template-columns:75px 1fr;gap:16px;padding:21px 4px 0}
.gallery-caption>span{font-size:9px;line-height:1.5;letter-spacing:.08em;font-weight:700;color:#6c7b6e}
.gallery-caption strong{font-size:14px;letter-spacing:-.01em}
.gallery-caption p{font-size:11px;line-height:1.6;color:#69746c;margin-top:9px}
.gallery-caption a{display:inline-block;font-size:9px;font-weight:700;letter-spacing:.1em;border-bottom:1px solid var(--ink);padding:12px 0 6px;margin-top:10px}
.credits{background:var(--accent);padding:32px 6% 100px}
.credits-top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #82934d;padding-bottom:20px;font-size:10px;letter-spacing:.13em;font-weight:700}
.credits-grid{display:grid;grid-template-columns:64% 36%;gap:20px;padding:82px 0 0}
.credits-grid h2{font:800 clamp(70px,8.3vw,136px)/.82 var(--display);letter-spacing:-.035em}
.credits-grid em{font-size:.84em}
.credits-info{padding:9px 10% 0 8%}
.credits-info>p:first-child{font-size:17px;line-height:1.65;font-weight:500}
.student{display:flex;flex-direction:column;margin:42px 0;padding:22px 0;gap:12px;border-top:1px solid #8ea05e;border-bottom:1px solid #8ea05e}
.student span,.student small{font-size:10px;letter-spacing:.13em;font-weight:700}
.student strong{font:700 32px var(--display)}
.legal{font-size:11px;line-height:1.8;opacity:.8}
.footer{background:#151b19;color:var(--paper);padding:40px 6% 25px}
.footer-toplink{display:flex;align-items:center;justify-content:flex-end;gap:20px;letter-spacing:.13em;font-size:10px;font-weight:700}
.footer-toplink span{font:32px var(--serif)}
.footer-name{font:800 clamp(87px,15vw,240px)/.9 var(--display);letter-spacing:-.04em;text-align:center;white-space:nowrap;padding:30px 0 42px}
.footer-name span{color:var(--accent)}
.footer-bottom{border-top:1px solid #56615b;display:flex;justify-content:space-between;gap:20px;padding-top:21px;font-size:9px;letter-spacing:.12em;color:#b5c0b7}
.js .reveal{opacity:0;transform:translateY(34px);transition:opacity .8s cubic-bezier(.2,.75,.2,1),transform .8s cubic-bezier(.2,.75,.2,1)}
.js .reveal.is-visible{opacity:1;transform:translateY(0)}
.js .hero h1 .title-line>span{transform:translateY(115%);animation:titleReveal 1.05s cubic-bezier(.2,.76,.15,1) forwards}
.js .hero h1 .title-line:nth-child(2)>span{animation-delay:.12s}
.js .hero h1 .title-line:nth-child(3)>span{animation-delay:.24s}
@keyframes titleReveal{to{transform:translateY(0)}}
@media(min-width:1500px){.site-header{padding-inline:max(6%,calc((100vw - 1680px)/2))}.hero-copy{padding-left:max(6vw,calc((100vw - 1680px)/2))}.profile,.purpose,.organization,.journal,.gallery,.credits,.footer{padding-left:max(6%,calc((100vw - 1680px)/2));padding-right:max(6%,calc((100vw - 1680px)/2))}}
