template-columns:1fr;gap:40px}.credits-grid h2{font-size:clamp(75px,12vw,135px)}.credits-info{padding:0;max-width:600px}.gallery-heading h2{font-size:clamp(64px,10vw,110px)}.gallery-heading p{padding-left:0}}
