block h3{font-size:35px}.mission-list li{gap:12px}.purpose-foot{font-size:28px;gap:8px}.org-layout{padding:55px 0;gap:42px}.org-intro>p{font-size:14px}.chart-lead{font-size:10px;padding:20px 15px}.department-grid{gap:6px}.department-grid span{font-size:9px;padding:16px 9px}.business-row{grid-template-columns:1fr 25px;gap:12px}.business-row>span:first-child{grid-column:1/-1}.business-row p{font-size:28px}.journal-layout{padding-top:53px}.journal-side h2{font-size:clamp(90px,19vw,129px)}.journal-main h3{font-size:clamp(47px,11.6vw,67px)}.journal-meta{font-size:8px;flex-wrap:wrap;justify-content:flex-start;gap:9px 16px}.journal-teaser{font-size:14px}.news-details summary{font-size:10px;letter-spacing:.07em}.gallery-heading{display:block;margin:56px 0 33px}.gallery-heading h2{font-size:clamp(64px,14.6vw,95px)}.gallery-heading p{padding:0;margin-top:28px;max-width:440px}.gallery-grid{grid-template-columns:1fr;gap:45px}.poster-item{grid-column:auto}.poster-design{min-height:470px}.poster-design h3{font-size:clamp(62px,14vw,86px)}.gallery-image-wrap,.gallery-image-wrap img{height:440px;min-height:440px}.gallery-caption{grid-template-columns:78px 1fr}.credits{padding:26px 5% 75px}.credits-top{font-size:9px}.credits-grid{padding-top:58px}.credits-grid h2{font-size:clamp(72px,15.7vw,108px)}.footer{padding:30px 5% 21px}.footer-name{font-size:clamp(67px,15.5vw,112px);padding:35px 0}.footer-bottom{font-size:8px;line-height:1.8;flex-direction:column;gap:6px}}
