@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.strip-track{animation:none}.js .reveal{opacity:1;transform:none;transition:none}.js .hero h1 .title-line>span{transform:none;animation:none}*,*::before,*::after{scroll-behavior:auto!important;transition-duration:.01ms!important;animation-duration:.01ms!important;animation-iteration-count:1!important}}


/* Blogger native post support */
.native-blog{background:#f3f2ec;color:#161b1a}
.native-blog-inner{padding:70px 6% 90px}
.native-post-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,310px),1fr));gap:22px;margin-top:32px}
.native-post-card{padding:32px 30px;border:1px solid #bdc3b9;background:#fbfbf6;display:flex;flex-direction:column;min-height:245px}
.native-post-kicker{font-size:10px;letter-spacing:.14em;font-weight:700;color:#9a5f37;margin-bottom:22px}
.native-post-card h2{font:700 clamp(34px,3.4vw,53px)/1 "Barlow Condensed",sans-serif;text-transform:uppercase;letter-spacing:-.02em;margin-bottom:18px}
.native-post-card h2 a:hover,.native-post-link:hover{color:#a5452b}
.native-snippet{font-size:13px;line-height:1.8;color:#55645b;margin-bottom:30px}
.native-post-link{display:flex;align-items:center;justify-content:space-between;gap:20px;border-top:1px solid #c1c8bd;padding-top:17px;font-size:10px;letter-spacing:.1em;font-weight:700;margin-top:auto}
.native-post-link span{font-size:18px}
.native-pager{display:flex;justify-content:space-between;margin-top:40px;font-size:12px;font-weight:700;gap:25px}
.native-single-post{max-width:900px;margin:0 auto;padding:80px 6% 125px;min-height:65vh}
.native-single-post h1{font:800 clamp(48px,7.5vw,100px)/.9 "Barlow Condensed",sans-serif;letter-spacing:-.035em;text-transform:uppercase;margin:34px 0 45px}
.native-back{font-size:10px;font-weight:700;letter-spacing:.1em;display:inline-block;border-bottom:1px solid #161b1a;padding-bottom:12px;margin-bottom:40px}
.native-post-body{font:400 15px/1.9 "DM Sans",sans-serif;overflow-wrap:break-word}
.native-post-body h2,.native-post-body h3{margin:34px 0 15px;font-family:"Barlow Condensed",sans-serif;line-height:1.1}
.native-post-body img{max-width:100%;height:auto}
.native-post-body p{margin-bottom:18px}
.native-post-body a{text-decoration:underline}
.native-post-body blockquote{border-left:3px solid #e16a45;padding-left:24px;margin-left:0;font-family:"Instrument Serif",serif;font-size:24px}
.native-post-body iframe{max-width:100%}
.native-post-body pre,.native-post-body code{max-width:100%;overflow:auto}
@media(max-width:600px){.native-blog-inner{padding:45px 5% 60px}.native-single-post{padding:55px 5% 90px}.native-post-card{padding:24px}.native-single-post h1{font-size:clamp(48px,12vw,75px)}}
/* Blogger can inject its own section/widget wrappers; keep spacing predictable. */
.native-blog .widget{margin:0;padding:0}

body.script:
//
(() => {
  'use strict';

  const header = document.querySelector('.site-header');
  const progress = document.querySelector('.scroll-progress');
  const button = document.querySelector('.menu-toggle');
  const navigation = document.querySelector('.nav');
  const links = [...document.querySelectorAll('.nav a')];
  const heroPhoto = document.querySelector('.hero-image');
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function closeMenu() {
    navigation.classList.remove('open');
    document.body.classList.remove('menu-open');
    button.setAttribute('aria-expanded', 'false');
    button.setAttribute('aria-label', 'Buka navigasi');
  }

  button?.addEventListener('click', () => {
    const opening = !navigation.classList.contains('open');
    navigation.classList.toggle('open', opening);
    document.body.classList.toggle('menu-open', opening);
    button.setAttribute('aria-expanded', String(opening));
    button.setAttribute('aria-label', opening ? 'Tutup navigasi' : 'Buka navigasi');
  });

  links.forEach(link => link.addEventListener('click', closeMenu));
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') closeMenu();
  });
  window.addEventListener('resize', () => {
    if (window.innerWidth > 880) closeMenu();
  });

  let framePending = false;
  function updateScrollEffects() {
    const scroll = Math.max(0, window.scrollY);
    const scrollable = Math.max(1, document.documentElement.scrollHeight - window.innerHeight);
    progress.style.width = (scroll / scrollable * 100).toFixed(2) + '%';
    header.classList.toggle('scrolled', scroll > 35);

    if (!reduceMotion && heroPhoto && scroll < window.innerHeight * 1.5) {
      heroPhoto.style.setProperty('--photo-shift', Math.min(17, scroll * 0.025).toFixed(2) + 'px');
    }
    framePending = false;
  }
  function requestScrollEffects() {
    if (!framePending) {
      framePending = true;
      window.requestAnimationFrame(updateScrollEffects);
    }
  }
  window.addEventListener('scroll', requestScrollEffects, { passive: true });
  updateScrollEffects();

  const revealElements = [...document.querySelectorAll('.reveal')];
  if (reduceMotion || !('IntersectionObserver' in window)) {
    revealElements.forEach(el => el.classList.add('is-visible'));
  } else {
    const revealObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        }
      });
    }, { rootMargin: '0px 0px -35px 0px', threshold: 0.09 });
    revealElements.forEach(el => revealObserver.observe(el));
  }

  const chapterIds = ['profil', 'arah', 'struktur', 'berita', 'galeri'];
  const chapters = chapterIds.map(id => document.getElementById(id)).filter(Boolean);
  if ('IntersectionObserver' in window) {
    const chapterObserver = new IntersectionObserver(entries => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        links.forEach(link => {
          const active = link.hash === '#' + entry.target.id;
          link.classList.toggle('active', active);
          if (active) link.setAttribute('aria-current', 'location');
          else link.removeAttribute('aria-current');
        });
      }
    }, { rootMargin: '-25% 0px -55% 0px', threshold: 0 });
    chapters.forEach(chapter => chapterObserver.observe(chapter));
  }
})();
//
